def test_maximal_independent_set_string_node_names(self):
    ht = hl.Table.parallelize([hl.Struct(i='A', j='B', kin=0.25), hl.Struct(i='A', j='C', kin=0.25), hl.Struct(i='D', j='E', kin=0.5)])
    ret = {row.node for row in hl.maximal_independent_set(ht.i, ht.j, False).collect()}
    assert ret in [{'A', 'D'}, {'A', 'E'}]
